# 推斷：資料表=舊版BOM與新版BOM（表頭第1列）｜欄位=料號｜主檔=舊版BOM與新版BOM｜鍵=料號｜篩選=新增/刪除｜輸出=新工作表「差異」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
old_ws = wb['舊版BOM']
new_ws = wb['新版BOM']

# 讀取舊版資料，以料號為鍵，其餘欄位為值
old_data = {}
for row in old_ws.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        old_data[row[0]] = row[1:]  # 品名, 數量, 類別, 單位

# 讀取新版資料
new_data = {}
for row in new_ws.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        new_data[row[0]] = row[1:]

# 計算新增與刪除的料號
added = set(new_data.keys()) - set(old_data.keys())
deleted = set(old_data.keys()) - set(new_data.keys())

# 建立新工作表（若已存在則先刪除）
if '差異' in wb.sheetnames:
    del wb['差異']
diff_ws = wb.create_sheet('差異')

# 寫入表頭
headers = ['差異類型', '料號', '品名', '數量', '類別', '單位']
diff_ws.append(headers)

# 先寫新增（資料來自新版BOM，依原表順序）
for part_no in new_data:
    if part_no in added:
        diff_ws.append(['新增', part_no] + list(new_data[part_no]))

# 再寫刪除（資料來自舊版BOM，依原表順序）
for part_no in old_data:
    if part_no in deleted:
        diff_ws.append(['刪除', part_no] + list(old_data[part_no]))

wb.save(OUTPUT_PATH)
