# 比對上期報價與本期報價，以品號為鍵，輸出新增/刪除項目至新工作表「差異比對」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_old = wb['上期報價']
ws_new = wb['本期報價']

# 讀取上期資料，以品號為鍵
old_data = {}
for row in ws_old.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        old_data[row[0]] = row

# 讀取本期資料
new_data = {}
for row in ws_new.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        new_data[row[0]] = row

old_keys = set(old_data.keys())
new_keys = set(new_data.keys())

added_keys = new_keys - old_keys
deleted_keys = old_keys - new_keys

# 建立新工作表
ws_diff = wb.create_sheet(title='差異比對')
ws_diff.append(['差異類型', '品號', '品名', '單價', '幣別', '計價單位'])

# 先列新增（按本期原表順序）
for key, row in new_data.items():
    if key in added_keys:
        ws_diff.append(('新增',) + row)

# 再列刪除（按上期原表順序）
for key, row in old_data.items():
    if key in deleted_keys:
        ws_diff.append(('刪除',) + row)

wb.save(OUTPUT_PATH)
