```python
# 推斷：資料表=上期報價、本期報價（表頭第 1 列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=上期報價｜鍵=品號（A 欄）｜篩選=欄位值變更｜輸出=新工作表「變更記錄」

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取兩個工作表
ws_prev = wb['上期報價']
ws_curr = wb['本期報價']

# 建立欄名→索引對照（表頭在第 1 列）
prev_headers = {cell.value: idx for idx, cell in enumerate(ws_prev[1], start=1)}
curr_headers = {cell.value: idx for idx, cell in enumerate(ws_curr[1], start=1)}

# 欄位順序（排除鍵「品號」）
key_col = 1  # 品號在 A 欄
compare_cols = [2, 3, 4, 5]  # 品名、單價、幣別、計價單位
col_names = {2: '品名', 3: '單價', 4: '幣別', 5: '計價單位'}

# 讀取上期報價資料（品號→整列資料）
prev_data = {}
prev_row_order = []  # 保持原順序
for row in range(2, ws_prev.max_row + 1):
    key = ws_prev.cell(row=row, column=key_col).value
    if key:
        prev_data[key] = {col: ws_prev.cell(row=row, column=col).value for col in compare_cols}
        prev_row_order.append((row, key))

